"""Synthetic LMTP and persisted-index inspection helpers. CC0-1.0."""
LMTP = "\nimport socket,sys,time,json\nuser,mid=sys.argv[1:3];payload=sys.stdin.buffer.read();rows=[]\nwith socket.socket(socket.AF_UNIX) as s:\n s.settimeout(30);s.connect('/run/dovecot/lmtp');f=s.makefile('rb')\n def reply(expected):\n  while True:\n   row=f.readline().decode().strip();assert row,rows;rows.append(row)\n   if row[3]!='-':assert int(row[:3])==expected,rows;return\n reply(220)\n for command in ['LHLO gate-b.sieve-expire.test','MAIL FROM:<sender@gate-b.sieve-expire.test>','RCPT TO:<'+user+'>']:\n  s.sendall((command+'\\r\\n').encode());reply(250)\n s.sendall(b'DATA\\r\\n');reply(354);start=time.time();mono=time.monotonic()\n s.sendall(payload+b'\\r\\n.\\r\\n');reply(250);end=time.time();elapsed=time.monotonic()-mono\n s.sendall(b'QUIT\\r\\n');reply(221)\nprint(json.dumps(dict(rows=rows,start=start,end=end,elapsed=elapsed,mid=mid)))\n"
COLLECT = "\nimport pathlib,subprocess,json,re,struct,hashlib,sys\nroot=pathlib.Path(sys.argv[1]);out={}\nfor directory in [root]+sorted(root.glob('.*')):\n if not directory.is_dir() or not (directory/'dovecot.index.log').exists():continue\n name='INBOX' if directory==root else directory.name[1:]\n text=subprocess.check_output(['doveadm','dump','-t','index',str(directory/'dovecot.index')],text=True);rows={}\n for part in text.split('RECORD: ')[1:]:\n  seq,uid=map(int,re.match(r'seq=(\\d+), uid=(\\d+)',part).groups())\n  match=re.search(r'sieve-expire-v2:\\s*\\(([0-9a-f]+)\\)',part)\n  pair=struct.unpack('<qq',bytes.fromhex(match[1])) if match else (0,0)\n  legacy=re.search(r'sieve-expire:[^\\n(]*\\(([0-9a-f]+)\\)',part)\n  rows[uid]=dict(seq=seq,expire_at=pair[0],expunge_at=pair[1],legacy_at=struct.unpack('<q',bytes.fromhex(legacy[1]))[0] if legacy else 0)\n uidlist=(directory/'dovecot-uidlist').read_text();messages={}\n for line in uidlist.splitlines()[1:]:\n  uid,entry=line.split(' ',1);uid=int(uid);fn=entry.split(':',1)[1]\n  files=list((directory/'new').glob(fn+'*'))+list((directory/'cur').glob(fn+'*'))\n  if not files:continue\n  assert len(files)==1,(name,uid,files)\n  raw=files[0].read_bytes();mid=re.search(rb'(?im)^Message-ID:\\s*<([^>]+)>',raw)[1].decode()\n  messages[mid]=dict(uid=uid,file=str(files[0]),sha256=hashlib.sha256(raw).hexdigest(),**rows.get(uid,dict(unindexed=True)))\n out[name]=dict(uidvalidity=int(re.search(r'^uid validity[^=]*=\\s*(\\d+)',text,re.M)[1]),next_uid=int(re.search(r'^next uid[^=]*=\\s*(\\d+)',text,re.M)[1]),records=rows,messages=messages,index=text,uidlist=uidlist,tmp=[str(p) for p in (directory/'tmp').glob('*')])\nprint(json.dumps(out))\n"
